CREATE TABLE "Device" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "state" TEXT NOT NULL, "category" TEXT NOT NULL DEFAULT 'ESSENTIAL', "isSheddable" BOOLEAN NOT NULL DEFAULT true, "powerUsage" REAL NOT NULL DEFAULT 0.0, "lastActionAt" DATETIME NOT NULL, "status" TEXT NOT NULL DEFAULT 'ONLINE');
CREATE TABLE "SystemConfig" ("id" TEXT NOT NULL PRIMARY KEY DEFAULT 'GLOBAL', "mode" TEXT NOT NULL DEFAULT 'STANDARD', "location" TEXT NOT NULL DEFAULT 'Home', "powerSource" TEXT NOT NULL DEFAULT 'MAINS', "autoShedding" BOOLEAN NOT NULL DEFAULT true, "version" TEXT NOT NULL DEFAULT '3.1.0-alpha');
CREATE TABLE "Alert" ("id" TEXT NOT NULL PRIMARY KEY, "type" TEXT NOT NULL, "severity" TEXT NOT NULL, "message" TEXT NOT NULL, "acknowledged" BOOLEAN NOT NULL DEFAULT false, "timestamp" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AccessProfile" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "pinHash" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'GUEST', "scheduleRaw" TEXT, "isTemporal" BOOLEAN NOT NULL DEFAULT false, "expiresAt" DATETIME);
CREATE TABLE "EnergyTelemetry" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "timestamp" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "voltage" REAL NOT NULL, "current" REAL NOT NULL, "frequency" REAL NOT NULL, "reactivePower" REAL NOT NULL DEFAULT 0.0, "powerFactor" REAL NOT NULL DEFAULT 1.0, "source" TEXT NOT NULL);
CREATE TABLE "SecurityAudit" ("id" TEXT NOT NULL PRIMARY KEY, "action" TEXT NOT NULL, "actor" TEXT NOT NULL, "status" TEXT NOT NULL, "timestamp" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "metadata" TEXT);
CREATE TABLE "GuestSession" ("id" TEXT NOT NULL PRIMARY KEY, "token" TEXT NOT NULL, "name" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'GUEST', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" DATETIME NOT NULL, "revoked" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "VoiceSettings" ("id" TEXT NOT NULL PRIMARY KEY DEFAULT 'GLOBAL', "persona" TEXT NOT NULL DEFAULT 'Ujo', "pitch" REAL NOT NULL DEFAULT 1.0, "speechRate" REAL NOT NULL DEFAULT 1.0);
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL PRIMARY KEY, "action" TEXT NOT NULL, "actor" TEXT NOT NULL, "timestamp" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "meta" TEXT);
CREATE TABLE "HardwareNode" ("id" TEXT NOT NULL PRIMARY KEY, "kind" TEXT NOT NULL, "room" TEXT, "firmwareVersion" TEXT, "status" TEXT NOT NULL DEFAULT 'OFFLINE', "provisioned" BOOLEAN NOT NULL DEFAULT false, "safetyClass" TEXT NOT NULL DEFAULT 'STANDARD', "allowedActions" TEXT NOT NULL DEFAULT '[]', "lastSequence" INTEGER NOT NULL DEFAULT -1, "commandSequence" INTEGER NOT NULL DEFAULT 0, "lastSeenAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HardwareCommand" ("id" TEXT NOT NULL PRIMARY KEY, "nodeId" TEXT NOT NULL, "action" TEXT NOT NULL, "value" TEXT, "status" TEXT NOT NULL DEFAULT 'PENDING', "requestedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" DATETIME NOT NULL, "approvedAt" DATETIME, "completedAt" DATETIME, "error" TEXT);
CREATE TABLE "SensorTelemetry" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "nodeId" TEXT NOT NULL, "kind" TEXT NOT NULL, "payload" TEXT NOT NULL, "timestamp" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "GuestSession_token_key" ON "GuestSession"("token");
CREATE INDEX "HardwareCommand_status_expiresAt_idx" ON "HardwareCommand"("status", "expiresAt");
CREATE INDEX "HardwareCommand_nodeId_createdAt_idx" ON "HardwareCommand"("nodeId", "createdAt");
CREATE INDEX "SensorTelemetry_nodeId_timestamp_idx" ON "SensorTelemetry"("nodeId", "timestamp");
CREATE INDEX "SensorTelemetry_kind_timestamp_idx" ON "SensorTelemetry"("kind", "timestamp");
